.c-dialog-demo {
  align-items: center;
  display: grid;
  justify-items: center;
  min-height: 100%;
  padding: 2rem;
}

.c-dialog {
  --dialog-accent: #b9f474;
  --dialog-accent-text: #162600;
  --dialog-muted: #62665d;
  --dialog-radius: 1rem;
  --dialog-surface: #ffffff;
  --dialog-text: #171915;
  --dialog-shadow: 0 1.5rem 5rem rgb(20 24 18 / 22%);

  background: var(--dialog-surface);
  border: 1px solid rgb(23 25 21 / 16%);
  border-radius: var(--dialog-radius);
  box-shadow: var(--dialog-shadow);
  color: var(--dialog-text);
  margin: auto;
  max-width: min(30rem, calc(100% - 2rem));
  padding: 0;
  width: 100%;
}

.c-dialog::backdrop {
  background: rgb(20 24 18 / 55%);
  backdrop-filter: blur(0.2rem);
}

.c-dialog__header {
  padding: 1.6rem 1.6rem 0.75rem;
}

.c-dialog__eyebrow {
  color: var(--dialog-muted);
  display: block;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.c-dialog h2 {
  font-size: clamp(1.55rem, 5vw, 2rem);
  letter-spacing: -0.04em;
  line-height: 1.05;
  margin: 0.55rem 0 0;
}

.c-dialog__body {
  color: var(--dialog-muted);
  line-height: 1.6;
  margin: 0;
  padding: 0 1.6rem 1.6rem;
}

.c-dialog__actions {
  border-top: 1px solid rgb(23 25 21 / 12%);
  display: flex;
  gap: 0.65rem;
  justify-content: flex-end;
  padding: 1rem 1.6rem;
}

.c-button {
  background: transparent;
  border: 1px solid rgb(23 25 21 / 30%);
  border-radius: 0.55rem;
  color: inherit;
  cursor: pointer;
  font: inherit;
  font-weight: 650;
  min-height: 2.75rem;
  padding: 0.65rem 1rem;
}

.c-button:hover {
  border-color: currentColor;
}

.c-button:focus-visible {
  outline: 0.2rem solid color-mix(in srgb, var(--dialog-accent) 75%, #000000);
  outline-offset: 0.15rem;
}

.c-button--primary {
  background: var(--dialog-accent);
  border-color: var(--dialog-accent);
  color: var(--dialog-accent-text);
}

@media (max-width: 32rem) {
  .c-dialog__actions {
    align-items: stretch;
    flex-direction: column-reverse;
  }
}

@media (prefers-reduced-motion: reduce) {
  .c-dialog::backdrop {
    backdrop-filter: none;
  }
}

